package net.zartra.gui;
import org.junit.Test;import static org.junit.Assert.*;
public class Goal2ConditionVariableTest {
 @Test public void registryCoversEveryConditionAndRejectsMalformed(){ConditionRegistry r=new ConditionRegistry();assertEquals(ConditionEntry.Type.values().length,r.all().size());for(ConditionEntry.Type t:ConditionEntry.Type.values())assertNotNull(r.get(t));assertFalse(r.valid(new ConditionEntry(ConditionEntry.Type.CHANCE,"101")));assertFalse(r.valid(new ConditionEntry(ConditionEntry.Type.TIME_RANGE,"bad")));}
 @Test public void conditionSetOrdersCopiesAndSupportsMode(){ConditionSet s=new ConditionSet();ConditionEntry b=new ConditionEntry(ConditionEntry.Type.IS_OP,"");b.order=2;ConditionEntry a=new ConditionEntry(ConditionEntry.Type.IS_NOT_OP,"");a.order=0;s.entries.add(b);s.entries.add(a);assertSame(a,s.ordered().get(0));ConditionSet copy=s.copy();copy.entries.get(0).enabled=false;assertTrue(s.entries.get(0).enabled);}
 @Test public void variablesHavePersistentAndEphemeralScopes(){VariableStore v=new VariableStore();java.util.UUID u=java.util.UUID.randomUUID();v.setGlobal("site.mode","on");v.setPlayer(u,"rank","vip");v.setTemporary(u,"flash","yes",10000);v.setSession(u,"menu","step","one");assertEquals("on",v.resolve(u,"menu","GLOBAL:site.mode"));assertEquals("vip",v.resolve(u,"menu","PLAYER:rank"));assertEquals("yes",v.resolve(u,"menu","TEMP:flash"));assertEquals("one",v.resolve(u,"menu","SESSION:step"));v.clearSession(u);assertNull(v.resolve(u,"menu","SESSION:step"));}
 @Test public void variableActionsAreStrict(){VariableStore v=new VariableStore();java.util.UUID u=java.util.UUID.randomUUID();assertTrue(v.apply(u,"m","GLOBAL|count|2","SET"));assertTrue(v.apply(u,"m","GLOBAL|count|3","ADD"));assertEquals("5",v.global("count"));assertTrue(v.apply(u,"m","GLOBAL|enabled","TOGGLE"));assertEquals("true",v.global("enabled"));assertFalse(v.apply(u,"m","GLOBAL|../bad|x","SET"));}
}